import chromadb

client = chromadb.HttpClient(host="vectors.internal")
collection = client.get_collection("support_docs")


def answer(question, tenant):
    hits = collection.query(
        query_texts=[question],
        n_results=5,
        where={"tenant_id": tenant},
    )
    for meta in hits["metadatas"][0]:
        if meta["tenant_id"] != tenant:
            raise PermissionError("cross-tenant chunk returned")
    context = "\n".join(hits["documents"][0])
    return call_model(context + "\n\n" + question)
